mapper.select:
SELECT a.id, a.media_id, m.media_company_short AS media_short, a.name, a.os_type, a.access_type, a.pkg, a.download_url, a.enable, a.creator, a.create_time, a.updater, a.update_time, a.deleted, a.tenant_id FROM ssp_app a LEFT JOIN ssp_media m ON a.media_id = m.id
a.deleted = 0
AND a.media_id = #{reqVO.mediaId}
AND a.name LIKE CONCAT('%', #{reqVO.name}, '%')
AND a.os_type = #{reqVO.osType}
AND a.access_type = #{reqVO.accessType}
AND a.enable = #{reqVO.enable}
AND a.create_time BETWEEN #{reqVO.createTime[0]} AND #{reqVO.createTime[1]}
ORDER BY id DESC LIMIT #{pageSize} OFFSET #{offset}

SELECT COUNT(*)
FROM ssp_app a

    a.deleted = 0

        AND  a.media_id = #{reqVO.mediaId}


        AND  a.name LIKE CONCAT('%', #{reqVO.name}, '%')


        AND  a.os_type = #{reqVO.osType}


        AND  a.access_type = #{reqVO.accessType}


        AND  a.enable = #{reqVO.enable}


        AND  a.create_time BETWEEN #{reqVO.createTime[0]} AND #{reqVO.createTime[1]}
